package com.kisanprocure.repository; import com.kisanprocure.entity.Booking; import org.springframework.data.jpa.repository.*; import java.time.LocalDate; import java.util.*; public interface BookingRepository extends JpaRepository<Booking,Long>{ Optional<Booking> findByBookingId(String bookingId); List<Booking> findByFarmerIdOrderByCreatedAtDesc(Long farmerId); List<Booking> findByCentreIdAndSlotSlotDateOrderByTokenNumber(Long centreId,LocalDate date); }